// Ambient declarations for asset imports (previously provided by react-scripts;
// bun's bundler resolves these at build time).
declare module "*.png" { const src: string; export default src; }
declare module "*.jpg" { const src: string; export default src; }
declare module "*.jpeg" { const src: string; export default src; }
declare module "*.gif" { const src: string; export default src; }
declare module "*.svg" { const src: string; export default src; }
declare module "*.mp3" { const src: string; export default src; }
declare module "*.wav" { const src: string; export default src; }
declare module "*.scss";
declare module "*.css";
